namespace sv_f8582a3c55dd4cc4b6d2d332c7ce055a.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

public class ThemeInfo
{
    public Theme Theme { get; set; } = Theme.Light;
    public string AccentColor { get; set; } = "#0d6efd";
}

/// <summary>
/// Scoped service (per-circuit) that holds theme state and notifies subscribers on change.
/// </summary>
public class ThemeState
{
    private Theme _theme = Theme.Light;
    private string _accentColor = "#0d6efd";

    public Theme Theme => _theme;
    public string AccentColor => _accentColor;

    public event Action? OnChange;

    public void SetTheme(Theme theme)
    {
        if (_theme == theme) return;
        _theme = theme;
        OnChange?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (_accentColor == color) return;
        _accentColor = color;
        OnChange?.Invoke();
    }

    public void Set(Theme theme, string accentColor)
    {
        bool changed = _theme != theme || _accentColor != accentColor;
        _theme = theme;
        _accentColor = accentColor;
        if (changed) OnChange?.Invoke();
    }

    public ThemeInfo ToThemeInfo() => new() { Theme = _theme, AccentColor = _accentColor };
}

@rendermode InteractiveServer
@inject ThemeState ThemeState
@implements IDisposable

<span class="theme-indicator badge" style="background-color: @ThemeState.AccentColor;">
    @ThemeState.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeState.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        ThemeState.OnChange -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@inject ThemeState ThemeState
@implements IDisposable

<button class="btn btn-sm btn-outline-secondary" @onclick="Toggle">
    @(_icon)
</button>

@code {
    private string _icon = "☀️";

    protected override void OnInitialized()
    {
        ThemeState.OnChange += StateHasChanged;
        UpdateIcon();
    }

    private void Toggle()
    {
        var next = ThemeState.Theme switch
        {
            Theme.Light => Theme.Dark,
            Theme.Dark => Theme.System,
            _ => Theme.Light
        };
        ThemeState.SetTheme(next);
    }

    protected override void OnParametersSet() => UpdateIcon();

    private void UpdateIcon()
    {
        _icon = ThemeState.Theme switch
        {
            Theme.Light => "☀️",
            Theme.Dark => "🌙",
            _ => "💻"
        };
    }

    public void Dispose()
    {
        ThemeState.OnChange -= StateHasChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeState ThemeState
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="mb-3">
    <label class="form-label">Theme</label>
    <select class="form-select" @bind="SelectedTheme">
        @foreach (var t in Enum.GetValues<Theme>())
        {
            <option value="@t">@t</option>
        }
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color" @bind="SelectedColor" />
</div>

<button class="btn btn-primary" @onclick="Save">Save Preferences</button>

@if (_saved)
{
    <span class="text-success ms-2">✓ Saved</span>
}

@code {
    private Theme SelectedTheme;
    private string SelectedColor = "#0d6efd";
    private bool _saved;

    protected override void OnInitialized()
    {
        ThemeState.OnChange += OnThemeChanged;
        LoadFromState();
    }

    private void LoadFromState()
    {
        SelectedTheme = ThemeState.Theme;
        SelectedColor = ThemeState.AccentColor;
    }

    private void OnThemeChanged()
    {
        LoadFromState();
        InvokeAsync(StateHasChanged);
    }

    private void Save()
    {
        ThemeState.Set(SelectedTheme, SelectedColor);
        _saved = true;
    }

    public void Dispose()
    {
        ThemeState.OnChange -= OnThemeChanged;
    }
}

