namespace sv_f8582a3c55dd4cc4b6d2d332c7ce055a.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

public class ThemeInfo
{
    public Theme Theme { get; set; } = Theme.Light;
    public string AccentColor { get; set; } = "#0d6efd";
}

/// <summary>
/// Scoped service (per-circuit) that holds theme state and notifies subscribers on change.
/// </summary>
public class ThemeState
{
    private Theme _theme = Theme.Light;
    private string _accentColor = "#0d6efd";

    public Theme Theme => _theme;
    public string AccentColor => _accentColor;

    public event Action? OnChange;

    public void SetTheme(Theme theme)
    {
        if (_theme == theme) return;
        _theme = theme;
        OnChange?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (_accentColor == color) return;
        _accentColor = color;
        OnChange?.Invoke();
    }

    public void Set(Theme theme, string accentColor)
    {
        bool changed = _theme != theme || _accentColor != accentColor;
        _theme = theme;
        _accentColor = accentColor;
        if (changed) OnChange?.Invoke();
    }

    public ThemeInfo ToThemeInfo() => new() { Theme = _theme, AccentColor = _accentColor };
}

